INTRO = "When Seung-chan carries Ye-jin's heavy bags up to the flat because of her sprained wrist, Joon-mo grumbles about her clumsiness and letting men inside while quietly fretting over her injury. Listen to their conversation first."
STORY = [('joonmo', '넌 여기 또 왜 왔냐?', 'Why did you come here again?', [(697, '넌 여기 또 왜 왔냐')], ''), ('seungchan', '이거 들어 드리려고요. 예진 선배님 손목 다쳐서 아픕니다.', 'To carry these for her. Senior Ye-jin hurt her wrist and is in pain.', [(699, '들어드리려고요'), (702, '예진 선배님'), (703, '손목 다쳐서 아픕니다')], ''), ('joonmo', '자꾸 어디 넘어지고 또 칠칠맞게 뭐 하다 다쳤냐?', 'Always tripping somewhere—what clumsy thing were you doing to get hurt again?', [(706, '자꾸 어디 넘어지고'), (707, '또 칠칠맞게 어디 뭐하다 다쳤냐')], ''), ('yejin', '궁금하지도 않으면서 물어보지 마. 고맙다, 백승찬.', "Don't ask when you aren't even curious. Thanks, Baek Seung-chan.", [(708, '궁금하지도 않으면서 물어보지 마'), (709, '고맙다')], ''), ('seungchan', '저는 들어가 보겠습니다.', 'I will head home now.', [(710, '들어가고 있습니다')], ''), ('joonmo', '많이 다쳤냐?', 'Did you hurt it badly?', [(712, '많이 다쳤냐')], ''), ('yejin', '됐어, 뭘 언제부터 걱정해 줬다고.', 'Forget it, since when have you ever worried about me.', [(713, '됐어 뭘 언제부터 걱정해줬다고')], ''), ('joonmo', '걱정은 하지, 늘. 근데 왜 백승찬을 집에 자꾸 들이냐?', 'I always worry. Still, why do you keep letting Baek Seung-chan into the house?', [(715, '걱정은 하지 늘'), (717, '백승찬을 집에 자꾸 들이고 그러냐')], ''), ('yejin', '어제는 술 먹고 들이닥친 거고 오늘은 짐 들어 준 거잖아.', 'Yesterday he barged in drunk, and today he just carried my bags.', [(719, '어제는 술 먹고 들이닥친거고'), (720, '오늘은 짐')], ''), ('joonmo', '겁도 없이 혼자 있을 때 남자 집에 들어오라고 하는 거 아니야.', "You shouldn't fearlessly invite a man inside when you are home alone.", [(723, '겁도 없이'), (724, '혼자 있을 때 남자 집에 들어오라고 하고 그러는 거 아니라고')], ''), ('yejin', '웃겨? 야, 넌 남자 아니냐? 내일 촬영 준비나 해.', "Funny, aren't you a man too? Go get ready for tomorrow's shoot.", [(725, '웃겨? 야, 넌 남자 아니냐'), (728, '내일 촬영 준비')], ''), ('joonmo', '서너 시간만 자다가 새벽에 나가야 돼. 아침 챙겨 먹어라.', 'I can only sleep three or four hours before leaving at dawn. Make sure you eat breakfast.', [(730, '서너 시간만 자다가 새벽에 나가야 돼'), (733, '아침 챙겨 먹어라')], '')]
OPENER = "Now let's go through it line by line with the English translation."
